set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
runuser -u news-flow -- /opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gzipSync} from 'node:zlib';import {createHash} from 'node:crypto';import axios from 'axios';import {NewsProxyPool} from './src/newsFlow/transport.mjs';import {createNewsProxyAgent} from './src/newsFlow/httpRequest.mjs';const root='/var/lib/news-flow/qc-recover25-20261122',pool=await NewsProxyPool.load('/etc/news-flow/proxies.json',{rotation:'request'}),r={at:new Date().toISOString(),checks:[]};for(const site of ['tieudungso.vn','dailo.vn','kinhteplus.com.vn'])for(const version of ['TLSv1.2','TLSv1.3'])for(const proxy of pool.proxies.slice(0,2)){const url='https://'+site+'/',c=new AbortController(),timer=setTimeout(()=>c.abort(),5000),agent=createNewsProxyAgent(proxy,c.signal,url,5000);agent.options={...agent.options,minVersion:version,maxVersion:version,ALPNProtocols:['http/1.1']};const o={site,url,version,proxyId:proxy.id,tlsVerification:'strict'};try{const p=await axios.get(url,{proxy:false,httpsAgent:agent,httpAgent:agent,signal:c.signal,timeout:5000,maxRedirects:0,validateStatus:()=>true,responseType:'arraybuffer',maxContentLength:4000000,headers:{'User-Agent':'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 Chrome/130.0.0.0 Safari/537.36'}});o.statusCode=p.status;o.location=p.headers.location;if(p.data?.length){o.file=root+'/evidence/'+createHash('sha256').update(p.data).digest('hex')+'.gz';fs.writeFileSync(o.file,gzipSync(p.data));}}catch(e){o.error=e.code||'NETWORK_ERROR';}finally{clearTimeout(timer);agent.destroy();}r.checks.push(o);console.log(JSON.stringify({...o,file:undefined}));}r.finishedAt=new Date().toISOString();fs.writeFileSync(root+'/tls-version-controls.json',JSON.stringify(r,null,2));
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-recover25-20261122/tls-version-controls.json "$upload_dir/.qc-recover25-tls-version-controls.json"
